{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SFUCCHECK AS SELECT sf.*, uc.order_name as uc_statusas FROM snitch_db.maplemonk.fact_items_snitch sf LEFT JOIN snitch_db.maplemonk.warehouse_sla_performance uc ON sf.order_name = uc.order_name WHERE LOWER(COALESCE(tags, \'\')) NOT LIKE \'%eco%\' AND LOWER(COALESCE(tags, \'\')) NOT LIKE \'%rms%\' AND LOWER(COALESCE(tags, \'\')) NOT LIKE \'%exch%\' AND sf.order_timestamp >= \'2026-01-01\' and city_mapped != \'TEST\' AND uc.order_name is null and sf.order_status not in (\'CANCELLED\') order by order_timestamp asc ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.UCLOGICCHECK AS WITH logic_items AS ( SELECT _airbyte_data:\"Order_No\"::STRING AS order_no, _airbyte_data:\"Gr_Number\"::STRING AS gr_number, item.value:\"AddlItemCode\"::STRING AS logic_sku, TO_DATE( _airbyte_data:\"Bill_Date\"::STRING, \'DD/MM/YYYY\' ) AS bill_date FROM snitch_db.maplemonk._airbyte_raw_logicerpnew_get_sale_invoice, LATERAL FLATTEN( INPUT => TRY_PARSE_JSON(_airbyte_data:\"LstItems\"::STRING) ) item WHERE _airbyte_data:\"Branch_Code\"::STRING IN (\'2\', \'8\', \'94\') AND TO_DATE( _airbyte_data:\"Bill_Date\"::STRING, \'DD/MM/YYYY\' ) BETWEEN DATEADD(DAY, -2, CURRENT_DATE()) AND CURRENT_DATE() QUALIFY ROW_NUMBER() OVER ( PARTITION BY _airbyte_data:\"Order_No\"::STRING, _airbyte_data:\"Gr_Number\"::STRING, item.value:\"AddlItemCode\"::STRING ORDER BY TO_DATE( _airbyte_data:\"Bill_Date\"::STRING, \'DD/MM/YYYY\' ) DESC ) = 1 ), logic_non_flip_invoice AS ( SELECT DISTINCT order_no FROM logic_items WHERE NULLIF(TRIM(order_no), \'\') IS NOT NULL ), logic_flip_invoice AS ( SELECT DISTINCT gr_number FROM logic_items WHERE NULLIF(TRIM(gr_number), \'\') IS NOT NULL ), uc_base AS ( SELECT awb, order_name, invoice_code, dispatched_timestamp, marketplace_mapped, sku, selling_price, warehouse_name, invoice_date FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 WHERE dispatched_timestamp IS NOT NULL AND dispatched_timestamp::DATE = DATEADD(DAY, -1, CURRENT_DATE()) AND sku <> \'DUMMY-BOX-01\' AND warehouse_name NOT ILIKE \'%surat-VRMall%\' AND marketplace_mapped IN ( \'FLIPKART_SOR\', \'MYNTRA_SJIT\', \'M-NOW\', \'SLIKK\', \'M_NOW_WESTBENGAL\', \'KNOT\', \'ZILO\', \'INSTAMART\', \'AJIO\', \'MYNTRA\', \'SHOPIFY\', \'FLIPKART\', \'AMAZON\', \'NYKAA.COM\', \'NYKAA_FASHION\', \'COCOBLU\', \'NOON\', \'STORE\', \'COCOBLU_WH2\', \'COCOBLU_WH1\', \'COCOBLU_NORTH\' ) ), non_flip AS ( SELECT uc.awb, uc.order_name, uc.invoice_code, uc.dispatched_timestamp, uc.marketplace_mapped, uc.sku, uc.selling_price, uc.warehouse_name, uc.invoice_date, CASE WHEN inv.order_no IS NULL THEN \'INVOICE_MISSING\' WHEN li.logic_sku IS NULL THEN \'ITEM_MISSING\' ELSE \'MATCHED\' END AS reconciliation_status FROM uc_base uc LEFT JOIN logic_non_flip_invoice inv ON TRIM(uc.invoice_code) = TRIM(inv.order_no) LEFT JOIN logic_items li ON TRIM(uc.invoice_code) = TRIM(li.order_no) AND TRIM(uc.sku) = TRIM(li.logic_sku) WHERE uc.marketplace_mapped NOT IN ( \'FLIPKART\', \'FLIPKART_SOR\' ) ), flip AS ( SELECT uc.awb, uc.order_name, uc.invoice_code, uc.dispatched_timestamp, uc.marketplace_mapped, uc.sku, uc.selling_price, uc.warehouse_name, uc.invoice_date, CASE WHEN inv.gr_number IS NULL THEN \'INVOICE_MISSING\' WHEN li.logic_sku IS NULL THEN \'ITEM_MISSING\' ELSE \'MATCHED\' END AS reconciliation_status FROM uc_base uc LEFT JOIN logic_flip_invoice inv ON TRIM(uc.awb) = TRIM(inv.gr_number) LEFT JOIN logic_items li ON TRIM(uc.awb) = TRIM(li.gr_number) AND TRIM(uc.sku) = TRIM(li.logic_sku) ), combined AS ( SELECT * FROM non_flip UNION ALL SELECT * FROM flip ) SELECT * FROM combined WHERE reconciliation_status IN ( \'INVOICE_MISSING\', \'ITEM_MISSING\' ) ORDER BY dispatched_timestamp ASC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            